# SPOTTER Social Enrichment (n8n-direct).
# Calls the maigret-api (username search) and linkedin-api (name/company lookup)
# sidecars directly, then writes SocialProfile nodes + HAS_PROFILE edges via the
# Flowsint API. Scope: real people (first+last name) OR is_high_value targets;
# machine ($)/service/krbtgt accounts skipped. Bounded per run + incremental via
# the social_enriched flag, so repeated fires walk the backlog.
import sys, os, re, json as _json
sys.path.insert(0, '/data/scripts')
import flowsint_client as fc
import requests as req
from datetime import datetime, timezone
from urllib.parse import urlparse, quote as _url_quote

FLOWSINT_URL = os.environ.get('FLOWSINT_API_URL', 'http://flowsint-api:5001').rstrip('/')
KEY          = os.environ.get('FLOWSINT_API_KEY', '')
_sb = _items[0].get('json', {}) if _items else {}
_sb = _sb.get('body', _sb) if isinstance(_sb.get('body'), dict) else _sb
# The Daily Sweep trigger carries no body, so reading the body alone pinned every
# scheduled run to $FLOWSINT_SKETCH_ID -- a sketch that does not exist on this
# host. A missing sketch returns clean zeros rather than erroring, so the run
# would enrich nobody and still record production_success. Resolve the active
# campaign for body-less runs; env is the last-resort fallback only.
SK = str(_sb.get('sketch_id') or '').strip()
if not SK:
    try:
        SK = fc.resolve_campaign_sketch()
    except Exception:
        SK = os.environ.get('FLOWSINT_SKETCH_ID', '')
MAIGRET_URL  = os.environ.get('MAIGRET_API_URL', 'http://maigret-api:7050').rstrip('/')
LINKEDIN_URL = os.environ.get('LINKEDIN_API_URL', 'http://linkedin-api:7051').rstrip('/')
MAX_PER_RUN  = int(os.environ.get('SOCIAL_MAX_PER_RUN', '25'))
MG_TOP       = int(os.environ.get('SOCIAL_MAIGRET_TOP_SITES', '25'))
MG_TO        = int(os.environ.get('SOCIAL_MAIGRET_TIMEOUT', '6'))
MG_MAX_UNAMES = int(os.environ.get('SOCIAL_MAIGRET_MAX_USERNAMES', '1'))
# Per-region site budget. Maigret filters by tag BEFORE ranking and slicing, so
# this is a real top-N of that region's platforms, not an intersection with the
# global top-N (ru ~41 sites, cn ~31, us ~40 at 40).
REGION_TOP      = int(os.environ.get('SOCIAL_MAIGRET_REGION_TOP_SITES', '40'))
DEFAULT_REGIONS = os.environ.get('SOCIAL_DEFAULT_REGIONS', '')
# socid-extractor second stage: open each discovered profile and mine it for
# identifiers. Runs against maigret-api, which already ships socid-extractor as a
# maigret dependency -- there is no separate sidecar.
SOCID_ENABLED  = os.environ.get('SOCIAL_SOCID_ENABLED', '1').strip().lower() not in ('0', 'false', 'no', '')
SOCID_MAX_URLS = int(os.environ.get('SOCIAL_SOCID_MAX_URLS', '12'))
SOCID_TIMEOUT  = int(os.environ.get('SOCIAL_SOCID_TIMEOUT', '15'))
H  = {'Authorization': f'Bearer {KEY}'}
HJ = {'Authorization': f'Bearer {KEY}', 'Content-Type': 'application/json'}

item   = _items[0].get('json', {}) if _items else {}
body   = item.get('body', item) if isinstance(item.get('body'), dict) else item
entity = body.get('entity', {}) if isinstance(body.get('entity'), dict) else {}
single_id    = (entity.get('id') or body.get('entity_id') or '').strip()
single_label = (entity.get('label') or body.get('entity_label') or '').strip().lower()
req_company  = (body.get('company') or '').strip()

# ── Regional platform coverage ────────────────────────────────────────────────
# These are Maigret site-DB tags and they are ADDITIVE to the global sweep, never
# a filter on it. That is not a style preference: maigret tags only 61 sites 'us'
# and 32 'cn', and GitHub/Instagram/Twitter/LinkedIn/Facebook carry no country tag
# at all, so filtering by region would drop every major platform and return a
# handful of niche consumer sites instead.
# The body wins; a body-less run (the Daily Sweep schedule trigger) falls back to
# SOCIAL_DEFAULT_REGIONS, empty by default = global only = pre-feature behaviour.
VALID_REGIONS = ('us', 'ru', 'cn')
_raw_regions = body.get('social_regions')
if not isinstance(_raw_regions, list) or not _raw_regions:
    _raw_regions = [x for x in DEFAULT_REGIONS.replace(' ', '').split(',') if x]
_want_regions = {str(x or '').strip().lower() for x in _raw_regions}
REGIONS = [r for r in VALID_REGIONS if r in _want_regions]

# ── Egress: proxy/opsec envelope ──────────────────────────────────────────────
# withInfraPayload() has been attaching proxy/opsec to every enrichment request
# all along and this workflow ignored both. It matters now: the regional sweeps
# probe VK / Odnoklassniki / Yandex / Weibo and the socid stage opens the profile
# pages themselves, so without this the operator's real source IP is what those
# platforms log. Envelope shape is WF13's -- socks_url preferred, socks{} as the
# fallback. proxy['ssh_tunnel'] is still unread by every workflow.
def _proxy_url_from_envelope(proxy):
    if not isinstance(proxy, dict):
        return ''
    if proxy.get('enabled') is False:
        return ''
    ptype = str(proxy.get('type') or '').strip().lower()
    if ptype == 'http':
        return str(proxy.get('http_url') or '').strip()
    if ptype in ('socks5', 'tor'):
        direct = str(proxy.get('socks_url') or '').strip()
        if direct:
            return direct
        socks = proxy.get('socks') if isinstance(proxy.get('socks'), dict) else {}
        host = str(socks.get('host') or '').strip()
        port = str(socks.get('port') or '').strip()
        if not host or not port:
            return ''
        user = str(socks.get('username') or '').strip()
        pw = str(socks.get('password') or '').strip()
        auth = ''
        if user:
            auth = _url_quote(user, safe='')
            if pw:
                auth += ':' + _url_quote(pw, safe='')
            auth += '@'
        return 'socks5h://' + auth + host + ':' + port
    return ''

proxy_cfg = body.get('proxy') if isinstance(body.get('proxy'), dict) else {}
opsec_cfg = body.get('opsec') if isinstance(body.get('opsec'), dict) else {}
SOCIAL_PROXY_URL = _proxy_url_from_envelope(proxy_cfg)
SOCIAL_UA = str(opsec_cfg.get('user_agent') or '').strip()[:256]

try:
    # Two labels instead of the whole sketch: the full-graph endpoint is unpaginated
    # (110-235s, ~0.5 GB on an AD-sized sketch) and truncates at 100k nodes, so both
    # the candidate list and the SocialProfile dedup below were built from an
    # arbitrary subset. Both label casings are fetched -- the enrichers MERGE
    # `:socialprofile` (lowercase) while this node writes `SocialProfile`.
    nds = fc.get_nodes_by_type(
        ['individual', 'socialprofile', 'SocialProfile'], sketch_id=SK)
except Exception as e:
    return [{'json': {'error': f'graph fetch failed: {e}', 'processed': 0}}]

inds = [n for n in nds if (n.get('nodeType') or '').lower() == 'individual']

existing_sp = {}
for n in nds:
    # Case-insensitive: nodeType mirrors the Neo4j label exactly, and the maigret /
    # linkedin enrichers create lowercase `socialprofile`. The old `== 'SocialProfile'`
    # never matched those, so enricher-created profiles were re-created here.
    if (n.get('nodeType') or '').lower() == 'socialprofile':
        existing_sp[(n.get('nodeLabel') or '').lower()] = n['id']

# Profiles already mined by socid, keyed on node id so a re-run does not refetch
# every page it has already opened. add_sp() returns the id of a deduped existing
# profile too, which is exactly what makes this check worth having.
sp_mined = set()
for n in nds:
    if (n.get('nodeType') or '').lower() == 'socialprofile' and (n.get('nodeProperties') or {}).get('socid_enriched'):
        sp_mined.add(n['id'])

def in_scope(n):
    p = n.get('nodeProperties') or {}
    if single_id:
        return n.get('id') == single_id
    if single_label:
        nl = (n.get('nodeLabel') or '').strip().lower()
        if nl == single_label:
            return True
        for k in ('label', 'full_name', 'sam_account_name', 'username', 'email'):
            if (p.get(k) or '').strip().lower() == single_label:
                return True
        return False
    sam = (p.get('sam_account_name') or p.get('username') or '')
    if sam.endswith('$'):
        return False
    low = sam.lower()
    if any(h in low for h in ('krbtgt', 'healthmailbox', 'svc_', 'svc-', '$')):
        return False
    if p.get('is_high_value'):
        return True
    fn = (p.get('first_name') or '').strip()
    ln = (p.get('last_name') or '').strip()
    return bool(fn and ln)

cand = [n for n in inds if in_scope(n)]

# Plugin ownership mode: workflow acts as orchestrator only.
# It no longer writes SocialProfile nodes/flags directly when plugin ownership
# is enabled; instead it triggers configured Flowsint enricher flows.
SOCIAL_OWNER = os.environ.get('SOCIAL_ENRICHMENT_OWNER', 'plugin').strip().lower()
plugin_flow_ids = {
    'maigret': os.environ.get('SOCIAL_MAIGRET_FLOW_ID', '').strip(),
    'linkedin': os.environ.get('SOCIAL_LINKEDIN_FLOW_ID', '').strip(),
}
enabled_plugin_flows = [name for name, fid in plugin_flow_ids.items() if fid]

def _plugin_pending(n):
    p = n.get('nodeProperties') or {}
    if not enabled_plugin_flows:
        return True
    if 'maigret' in enabled_plugin_flows and not p.get('maigret_enriched'):
        return True
    if 'linkedin' in enabled_plugin_flows and not p.get('linkedin_enriched'):
        return True
    return False

if not (single_id or single_label):
    if SOCIAL_OWNER == 'plugin':
        cand = [n for n in cand if _plugin_pending(n)]
    else:
        cand = [n for n in cand if not (n.get('nodeProperties') or {}).get('social_enriched')]
    cand.sort(key=lambda n: 0 if (n.get('nodeProperties') or {}).get('is_high_value') else 1)
    cand = cand[:MAX_PER_RUN]

if SOCIAL_OWNER == 'plugin':
    entity_ids = [n.get('id', '') for n in cand if n.get('id')]
    trigger_defs = [(name, fid) for name, fid in plugin_flow_ids.items()]

    triggered = []
    trigger_errors = []

    for flow_name, flow_id in trigger_defs:
        if not flow_id:
            continue
        try:
            resp = req.post(
                f'{FLOWSINT_URL}/api/flows/{flow_id}/run',
                headers=HJ,
                json={'sketch_id': SK, 'entities': [{'id': eid} for eid in entity_ids]},
                timeout=45,
            )
            if resp.status_code >= 400:
                preview = resp.text[:200] if resp.text else ''
                raise RuntimeError(f'HTTP {resp.status_code}: {preview}')
            triggered.append({'flow': flow_name, 'flow_id': flow_id})
        except Exception as e:
            trigger_errors.append({'flow': flow_name, 'flow_id': flow_id, 'error': str(e)})

    if not entity_ids:
        status = 'ok_no_targets'
    elif trigger_errors and triggered:
        status = 'partial_with_errors'
    elif trigger_errors and not triggered:
        status = 'error'
    elif not triggered:
        status = 'misconfigured'
    else:
        status = 'ok'

    return [{'json': {
        'mode': 'single' if (single_id or single_label) else 'sweep',
        'owner': 'plugin',
        'status': status,
        'candidate_count': len(cand),
        'target_entity_ids': entity_ids[:200],
        'triggered_flows': triggered,
        'trigger_errors': trigger_errors,
    }}]
now   = datetime.now(timezone.utc).isoformat()
stats = {'sp': 0, 'edges': 0, 'socid': 0, 'socid_fields': 0}

def add_sp(platform, username, url, extra=None):
    sp_label = f'{platform.title()}:{username}'
    k = sp_label.lower()
    if k in existing_sp:
        return existing_sp[k]
    props = {'platform': platform, 'username': username, 'url': url,
             'source': 'social-enrichment', 'discovered_at': now}
    if extra:
        props.update({kk: vv for kk, vv in extra.items() if vv not in (None, '')})
    try:
        r = req.post(f'{FLOWSINT_URL}/api/sketches/{SK}/nodes/add', headers=HJ,
                     json={'id': None, 'nodeLabel': sp_label, 'nodeType': 'SocialProfile',
                           'nodeMetadata': {}, 'nodeProperties': props}, timeout=20)
        r.raise_for_status()
        nid = (r.json().get('node') or r.json()).get('id', '')
        if nid:
            existing_sp[k] = nid
            stats['sp'] += 1
        return nid
    except Exception:
        return ''

def link(src, tgt, lbl):
    if not src or not tgt:
        return
    try:
        req.post(f'{FLOWSINT_URL}/api/sketches/{SK}/relations/add', headers=HJ,
                 json={'source': src, 'target': tgt, 'label': lbl, 'type': 'one-way'}, timeout=20)
        stats['edges'] += 1
    except Exception:
        pass

def _useful_profile(url, username):
    # Drop Maigret false positives that point at a bare domain with no per-user
    # path (e.g. "https://discord.com") and hits where the searched username
    # appears nowhere in the URL and there is no meaningful path.
    try:
        u = urlparse(url or '')
        if not u.netloc:
            return False
        path = (u.path or '').strip('/')
        if not path and not u.query:
            return False
        if username and username.lower() in (url or '').lower():
            return True
        return len(path) >= 2
    except Exception:
        return True

# socid-extractor output field -> SocialProfile property. Only names that already
# have a home on the declared schema are mapped; everything else is kept as an
# undeclared socid_* extra. That split is deliberate: a DB-registered custom type
# rebuilds every DECLARED property as Optional[str] and Pydantic then silently
# drops values it cannot coerce, so ints/bools (follower_count, is_verified) must
# stay undeclared to survive. SocialProfile sets extra = 'allow', so they do.
_SOCID_MAP = {
    'fullname': 'display_name', 'name': 'display_name', 'real_name': 'display_name',
    'bio': 'bio', 'about': 'bio', 'description': 'bio',
    'location': 'location', 'city': 'location',
    'image': 'photo_url', 'avatar': 'photo_url', 'photo': 'photo_url',
    'email': 'profile_emails',
}

def _socid_updates(xd):
    # Build a dotted-path update set for /nodes/edit. The nodeProperties. prefix is
    # mandatory -- an unprefixed key lands at the node's top level where no reader
    # looks, and every layer still reports success.
    data = xd.get('data') or {}
    upd = {}
    for k, v in data.items():
        if v in (None, '', [], {}):
            continue
        dest = _SOCID_MAP.get(str(k).lower())
        if dest == 'profile_emails':
            upd['nodeProperties.profile_emails'] = [str(x) for x in v] if isinstance(v, list) else [str(v)]
        elif dest:
            # setdefault: the raw profile page is mined before its API variants, and
            # two schemes can both offer a display_name. First non-empty wins.
            upd.setdefault('nodeProperties.' + dest, str(v)[:2000])
        else:
            safe = re.sub(r'[^a-z0-9_]', '_', str(k).lower()).strip('_')
            if safe:
                upd['nodeProperties.socid_' + safe] = v if isinstance(v, (int, float, bool)) else str(v)[:2000]
    if not upd:
        return {}
    stats['socid_fields'] += len(upd)
    upd['nodeProperties.socid_enriched'] = True
    upd['nodeProperties.socid_enriched_at'] = now
    if xd.get('scheme'):
        upd['nodeProperties.socid_scheme'] = xd['scheme']
    return upd

def mine_profile(sp_id, sp_url):
    # Open one already-discovered profile URL and merge whatever socid-extractor
    # can pull off it onto that SocialProfile node. Fail-soft: this is a bonus pass
    # over data we already have, so nothing here may break the enrichment run.
    if not sp_id or not sp_url or sp_id in sp_mined:
        return False
    sp_mined.add(sp_id)
    payload = {'url': sp_url, 'timeout': SOCID_TIMEOUT}
    if SOCIAL_PROXY_URL:
        payload['proxy_url'] = SOCIAL_PROXY_URL
    if SOCIAL_UA:
        payload['user_agent'] = SOCIAL_UA
    try:
        xr = req.post(f'{MAIGRET_URL}/extract', json=payload, timeout=SOCID_TIMEOUT * 3 + 20)
        if not xr.ok:
            return False
        xd = xr.json() or {}
        if not xd.get('found'):
            return False
        sp_upd = _socid_updates(xd)
        if not sp_upd:
            return False
        req.put(f'{FLOWSINT_URL}/api/sketches/{SK}/nodes/edit', headers=HJ,
                json={'nodeId': sp_id, 'updates': sp_upd}, timeout=20)
        stats['socid'] += 1
        return True
    except Exception:
        return False

results = []
for n in cand:
    p   = n.get('nodeProperties') or {}
    nid = n['id']
    label = n.get('nodeLabel') or ''
    fn = (p.get('first_name') or '').strip()
    ln = (p.get('last_name') or '').strip()
    full_name = (p.get('full_name') or p.get('display_name') or '').strip()
    if not full_name and fn and ln:
        full_name = f'{fn} {ln}'
    email = (p.get('email') or '').strip()
    sam   = (p.get('sam_account_name') or p.get('username') or '').strip()
    found = []
    li = None

    # ── LinkedIn (needs a plausible human full name) ──────────────────────────
    if full_name and ' ' in full_name:
        try:
            lr = req.post(f'{LINKEDIN_URL}/lookup',
                          json={'full_name': full_name, 'email': email or None,
                                'company': req_company or None}, timeout=45)
            if lr.ok:
                d = lr.json()
                if d.get('found') and d.get('url'):
                    li = d
                    slug = d['url'].rstrip('/').split('/in/')[-1] or full_name
                    sp = add_sp('linkedin', slug, d['url'],
                                {'job_title': d.get('job_title'), 'employer': d.get('employer'),
                                 'display_name': d.get('display_name') or full_name,
                                 'photo_url': d.get('photo_url'),
                                 'photo_source': 'linkedin' if d.get('photo_url') else None,
                                 'confidence': d.get('confidence')})
                    link(nid, sp, 'HAS_PROFILE')
                    found.append({'platform': 'linkedin', 'url': d['url']})
        except Exception:
            pass

    # ── Maigret (username variants: sam + email localpart) ────────────────────
    unames = []
    for u in [sam, (email.split('@')[0] if '@' in email else '')]:
        u = (u or '').strip().lower()
        if u and u not in unames and not u.endswith('$') and len(u) >= 3:
            unames.append(u)
    seen = set()
    discovered = []

    def sweep(u, tags, top):
        # One maigret pass. tags='' is the global top-sites sweep that has always
        # run; a region tag is an ADDITIONAL pass over that region's platform
        # family. Results from every pass share `seen`/existing_sp, so a profile
        # found both globally and regionally collapses to one node.
        payload = {'username': u, 'timeout': MG_TO, 'top_sites': top}
        if tags:
            payload['tags'] = tags
        if SOCIAL_PROXY_URL:
            payload['proxy_url'] = SOCIAL_PROXY_URL
        if SOCIAL_UA:
            payload['user_agent'] = SOCIAL_UA
        mr = req.post(f'{MAIGRET_URL}/search', json=payload, timeout=MG_TO * 4 + 90)
        if not mr.ok:
            return
        for prof in (mr.json().get('profiles') or []):
            pk = f"{prof.get('platform')}:{prof.get('username')}".lower()
            if pk in seen:
                continue
            seen.add(pk)
            if not _useful_profile(prof.get('url', ''), prof.get('username', '')):
                continue
            sp = add_sp(prof['platform'], prof['username'], prof['url'],
                        {'category': prof.get('category'), 'via_username': u,
                         'region': tags or None})
            link(nid, sp, 'HAS_PROFILE')
            found.append({'platform': prof['platform'], 'url': prof['url'], 'region': tags or None})
            if sp:
                discovered.append((sp, prof['url']))

    for u in unames[:MG_MAX_UNAMES]:
        # Each pass is independently guarded: one dead region (or a platform family
        # that blocks this egress outright) must not cost us the others.
        try:
            sweep(u, '', MG_TOP)
        except Exception:
            pass
        for rg in REGIONS:
            try:
                sweep(u, rg, REGION_TOP)
            except Exception:
                pass

    # ── socid-extractor: mine the profiles just discovered ────────────────────
    socid_hits = 0
    if SOCID_ENABLED:
        for sp_id, sp_url in discovered[:SOCID_MAX_URLS]:
            if mine_profile(sp_id, sp_url):
                socid_hits += 1

    # ── mark individual enriched + carry LinkedIn fields onto the node ────────
    upd = {'nodeProperties.social_enriched': True,
           'nodeProperties.social_enriched_at': now,
           'nodeProperties.social_profile_count': len(found)}
    if li:
        upd['nodeProperties.linkedin_url'] = li.get('url')
        if li.get('job_title'):
            upd['nodeProperties.linkedin_job_title'] = li['job_title']
        if li.get('employer'):
            upd['nodeProperties.linkedin_employer'] = li['employer']
        if li.get('photo_url'):
            upd['nodeProperties.linkedin_photo'] = li['photo_url']
    try:
        req.put(f'{FLOWSINT_URL}/api/sketches/{SK}/nodes/edit', headers=HJ,
                json={'nodeId': nid, 'updates': upd}, timeout=20)
    except Exception:
        pass
    results.append({'individual': label, 'full_name': full_name,
                    'profiles': len(found), 'linkedin': bool(li),
                    'regional_profiles': sum(1 for f in found if f.get('region')),
                    'socid_extracted': socid_hits})

return [{'json': {
    'mode': 'single' if (single_id or single_label) else 'sweep',
    'processed': len(cand),
    'social_profiles_created': stats['sp'],
    'has_profile_edges': stats['edges'],
    'with_linkedin': sum(1 for r in results if r['linkedin']),
    'regions': REGIONS,
    'socid_enabled': SOCID_ENABLED,
    'socid_extracted': stats['socid'],
    'socid_fields_written': stats['socid_fields'],
    'proxied': bool(SOCIAL_PROXY_URL),
    'results': results[:50],
}}]
